use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        // output length matches input length
        result.len() == a.len() &&
        // every element in output is 1
        forall |i: usize| (i < result.len() ==> result[i] == 1)
{
    let n = a.len();
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    spec fn loop_invariant(i: usize, out: &Vec<i32>) -> bool {
        // loop counter in [0..n]
        i <= n &&
        // output length equals number of iterations done
        out.len() == i &&
        // all written elements are 1
        forall |j: usize| (j < i ==> out[j] == 1)
    }

    while i < n
        invariant loop_invariant(i, &out)
        decreases n - i
    {
        out.push(1);
        i = i + 1;
    }

    result = out;
}

}
